    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def calculate_probability(total_tickets: int, chosen_tickets: int) -> float:
    """Calculate the probability that among the chosen tickets, there are at least 2 prime numbers and the sum of the numbers is even."""
    # Generate all possible combinations of chosen_tickets from total_tickets
    all_combinations = set()
    for i in range(total_tickets):
        for j in range(i + 1, total_tickets):
            for k in range(j + 1, total_tickets):
                for last in range(k + 1, total_tickets):
                    combination = tuple(sorted([i, j, k, last]))
                    all_combinations.add(combination)

    # Filter combinations with at least two prime numbers and even sum
    valid_combinations = set()
    for combination in all_combinations:
        if sum(combination) % 2 == 0:  # Check if the sum is even
            primes_in_combination = [num for num in combination if is_prime(num)]
            if len(primes_in_combination) >= 2:  # Check if there are at least two prime numbers
